func (f *Fake) Call(_ context.Context, method string, params map[string]any) (json.RawMessage, error) {
	if f.BeforeCall != nil {
		f.BeforeCall(method)
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	copyParams := make(map[string]any, len(params))
	for key, value := range params {
