	}
	f.Calls = append(f.Calls, CallRecord{Method: method, Params: copyParams})
	if !APIMethods[method] {
		return nil, &Error{Code: "invalid_request", Message: "unknown Herdr method " + method}
	}
	if queue := f.ErrorQueue[method]; len(queue) > 0 {
