// A normal command after a Herdr restart records it and relaunches nothing;
// `posse up --all` then restores the Lead and Workers (ADR 0035).
func TestListHoldsRestartUntilUpAll(t *testing.T) {
	fixture := newWorkerTabsFixture(t)
	before := fixture.start(t, "t1", "Tabs missing hook", "tabs-missing-hook")
	db, err := store.OpenReadOnly(fixture.home)
	if err != nil {
		t.Fatal(err)
	}
	oldGeneration, err := db.ProjectServerStartedAt(context.Background(), fixture.projectID)
	_ = db.Close()
	if err != nil || oldGeneration == "" {
		t.Fatalf("Project had no recorded generation before restart: %q, %v", oldGeneration, err)
	}
	killServer(t, fixture.server)
	fixture.server = startServer(t, fixture.client)
	newGeneration := fixture.snapshot(t).ServerStartedAt
	if newGeneration == oldGeneration {
		t.Fatalf("Herdr generation did not change: %q", newGeneration)
	}
	runPosse(t, fixture.binary, fixture.repo, fixture.env, "list")
	if current := fixture.task(t, "t1"); current.Launches != before.Launches || current.State != store.StateWorking {
		t.Fatalf("list relaunched or changed the Worker after a Herdr restart: before=%#v after=%#v", before, current)
	}
	if _, found := findLeadInSnapshot(fixture.snapshot(t)); found {
		t.Fatal("list restarted the Lead after a Herdr restart")
	}
	db, err = store.OpenReadOnly(fixture.home)
	if err != nil {
		t.Fatal(err)
	}
	notices, err := db.UndeliveredNotices(context.Background(), fixture.projectID)
	held, heldErr := db.ProjectServerStartedAt(context.Background(), fixture.projectID)
	_ = db.Close()
	restoreNotices := 0
	for _, notice := range notices {
		if notice.Kind == "restore_needed" && strings.Contains(notice.Summary, "posse up --all") {
			restoreNotices++
		}
	}
	if err != nil || heldErr != nil || restoreNotices != 1 || held != oldGeneration {
		t.Fatalf("held restart: restore_needed=%d generation=%q want %q notices=%#v err=%v %v", restoreNotices, held, oldGeneration, notices, err, heldErr)
	}
	output := runPosse(t, fixture.binary, fixture.repo, fixture.env, "up", "--all")
	after := fixture.task(t, "t1")
	if after.Launches != before.Launches+1 || after.AgentName == before.AgentName {
		t.Fatalf("up --all did not restore the Worker: before=%#v after=%#v output=%s", before, after, output)
	}
	var restored herdr.Pane
	for _, pane := range fixture.snapshot(t).Panes {
		if pane.Label == after.PaneLabel {
			restored = pane
		}
	}
	if restored.PaneID == "" || restored.PaneID != after.PaneID || restored.WorkspaceID != after.HerdrWorkspaceID || restored.CWD != after.WorktreePath {
		t.Fatalf("recovered Worker pane does not match its Task: pane=%#v task=%#v", restored, after)
	}
	recoveredSnapshot := fixture.snapshot(t)
	lead, found := findLeadInSnapshot(recoveredSnapshot)
	if !found {
		t.Fatal("recovered Lead is missing")
	}
	if after.HerdrWorkspaceID != lead.WorkspaceID {
		t.Fatalf("recovered Worker did not migrate into the Lead workspace: task=%#v Lead=%#v", after, lead)
	}
	foundTab := false
	for _, tab := range recoveredSnapshot.Tabs {
		if tab.WorkspaceID == lead.WorkspaceID && tab.TabID == restored.TabID && tab.Label == after.ShortName+"-t"+strconv.Itoa(after.Seq) {
			foundTab = true
		}
	}
	if !foundTab {
		t.Fatalf("recovered Worker tab is missing from the Lead workspace: %#v", recoveredSnapshot.Tabs)
	}
	assertLeadSidebarPresentation(t, fixture.client, lead.WorkspaceID, lead.PaneID, "Lead:shop")
	db, err = store.OpenReadOnly(fixture.home)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	generation, err := db.ProjectServerStartedAt(context.Background(), fixture.projectID)
	if err != nil || generation != newGeneration {
		t.Fatalf("Project generation after command = %q, want %q: %v", generation, newGeneration, err)
	}
}

