			if pane.Label == "posse:shop:t1" {
				paneID = pane.PaneID
				return true
			}
		}
		return false
	}) {
		t.Fatal("Worker tab never opened")
	}
	if _, err := f.client.Call(context.Background(), "pane.focus", map[string]any{"pane_id": paneID}); err != nil {
		t.Fatal(err)
	}
	if err := command.Wait(); err != nil {
		t.Fatalf("focused start: %v: %s", err, output.String())
	}
	if task := f.task(t, "t1"); task.State != store.StateWorking || task.SandboxID == 0 {
		t.Fatalf("focused Worker did not reach working with its Sandbox: %#v output=%s", task, output.String())
	}
	prompts, err := os.ReadFile(filepath.Join(f.root, "focused-launch-prompts"))
	if err != nil || !strings.Contains(string(prompts), "Read ") || !strings.Contains(string(prompts), "launch.md") {
		t.Fatalf("focused Worker did not receive its typed launch Brief: %q, %v", prompts, err)
	}
	if _, err := f.client.Call(context.Background(), "pane.focus", map[string]any{"pane_id": f.leadPaneID}); err != nil {
		t.Fatal(err)
	}
	focusEvent := setEnv(f.env, "HERDR_PLUGIN_EVENT_JSON", `{"event":"pane_focused","data":{"pane_id":"`+f.leadPaneID+`"}}`)
	runPosse(t, f.binary, f.repo, focusEvent, "_ingest")
	if task := f.task(t, "t1"); task.State != store.StateWorking {
		t.Fatalf("focus reconciliation changed launch state: task=%#v output=%s", task, output.String())
	}
	if task := f.task(t, "t1"); task.SandboxID == 0 || task.PaneID != paneID {
		t.Fatalf("queued launch did not use the same Sandbox and pane: %#v", task)
	}
}

// TestLegacyWorkerTabsAfterWorktreeUpgrade migrates freshly opened Workers into
// the former tab layout, then verifies reconcile, relaunch and Teardown still
// recognize them after the repository layout changes.
func TestLegacyWorkerTabsAfterWorktreeUpgrade(t *testing.T) {
	fixture := newWorkerTabsFixture(t)
	client := fixture.client

	first := fixture.startLegacy(t, "t1", "Tabs first worker", "tabs-first-worker")
	second := fixture.startLegacy(t, "t2", "Tabs second worker", "tabs-second-worker")
	snapshot := fixture.snapshot(t)
	fixture.assertUserLayout(t, snapshot)
	fixture.assertWorkerTab(t, snapshot, first)
	fixture.assertWorkerTab(t, snapshot, second)
	fixture.assertWorkerLabels(t, snapshot, first, second)
	fixture.assertRenderedSidebar(t, first, second)
	fixture.assertAlive(t, fixture.snapshot(t), fixture.leadPaneID)
	if tabOf(t, snapshot, first.PaneID) == tabOf(t, snapshot, second.PaneID) {
		t.Fatalf("two Workers share tab %s", tabOf(t, snapshot, first.PaneID))
	}
	if snapshot.FocusedPaneID != fixture.leadPaneID {
		t.Fatalf("start moved focus off the Lead to %s", snapshot.FocusedPaneID)
	}

	// A foreign split in the first Worker's tab survives its teardown.
	foreign := fixture.split(t, first.PaneID, fixture.root)
	// An unlabeled pane inside the second Sandbox but in a User workspace is not the Worker's pane.
	// The first teardown must not touch the second Worker's Sandbox.
	stray := fixture.split(t, fixture.userAfter.RootPane.PaneID, second.WorktreePath)
	fixture.fail(t, "t1")
	fixture.exitWorker(t, "t1")
	if _, err := client.Call(context.Background(), "pane.close", map[string]any{"pane_id": first.PaneID}); err != nil {
		t.Fatalf("close the exited Task pane without closing its foreign split: %v", err)
	}
	output := runPosse(t, fixture.binary, fixture.repo, fixture.leadEnv, "teardown", "t1", "--discard", "--user-approved", "User approved the tab teardown test")
	if !strings.Contains(output, "torn-down") {
		t.Fatalf("approved discard after closing the exited pane failed: %s", output)
	}
	snapshot = fixture.snapshot(t)
	fixture.assertUserLayout(t, snapshot)
	fixture.assertWorkerLabels(t, snapshot, second)
	fixture.assertAlive(t, snapshot, second.PaneID, foreign, fixture.leadPaneID)
	fixture.assertGone(t, snapshot, first.PaneID)

	// The User closes the second Worker's tab after its agent exits; discard must not steal focus.
	ownSplit := fixture.split(t, second.PaneID, second.WorktreePath)
	if _, err := client.Call(context.Background(), "pane.focus", map[string]any{"pane_id": second.PaneID}); err != nil {
		t.Fatal(err)
	}
	secondTab := tabOf(t, fixture.snapshot(t), second.PaneID)
	fixture.fail(t, "t2")
	fixture.exitWorker(t, "t2")
	if _, err := client.Call(context.Background(), "tab.close", map[string]any{"tab_id": secondTab}); err != nil {
		t.Fatalf("close the exited Task tab and its shell-only split: %v", err)
	}
	if _, err := client.Call(context.Background(), "pane.close", map[string]any{"pane_id": stray}); err != nil {
		t.Fatalf("close the fixture-owned split in the second Sandbox: %v", err)
	}
	focusedBeforeTeardown := fixture.snapshot(t).FocusedPaneID
	output = runPosse(t, fixture.binary, fixture.repo, fixture.leadEnv, "teardown", "t2", "--discard", "--user-approved", "User approved the focused tab teardown test")
	if !strings.Contains(output, "torn-down") {
		t.Fatalf("approved discard after closing the exited tab failed: %s", output)
	}
	snapshot = fixture.snapshot(t)
	fixture.assertUserLayout(t, snapshot)
	fixture.assertWorkerLabels(t, snapshot)
	fixture.assertGone(t, snapshot, second.PaneID, ownSplit, stray)
	fixture.assertAlive(t, snapshot, foreign)
	for _, tab := range snapshot.Tabs {
		if tab.TabID == secondTab {
			t.Fatalf("focused Worker tab %s survived teardown", secondTab)
		}
	}
	if snapshot.FocusedPaneID != focusedBeforeTeardown {
		t.Fatalf("discard changed focus from %s to %s", focusedBeforeTeardown, snapshot.FocusedPaneID)
	}
	// The foreign split has served its teardown-ownership assertion. Close this
	// fixture-owned shell before the separate Herdr restart/recovery exercise.
	if _, err := client.Call(context.Background(), "pane.close", map[string]any{"pane_id": foreign}); err != nil {
		t.Fatalf("close fixture-owned foreign split: %v", err)
	}

	// Relaunch after an upgrade uses the new child layout. Move it back to a
	// legacy tab to exercise restart and tab-scoped Teardown.

