292: 			lastErr = send(attemptCtx, "agent.send_keys", map[string]any{"target": paneID, "keys": []string{"enter"}})
293: 			if lastErr == nil {
294: 				_, lastErr = s.herdrCall(attemptCtx, "agent.wait", map[string]any{"target": paneID, "until": activity["until"], "timeout_ms": activity["timeout_ms"]})
295: 			}
296: 		} else {
297: 			pressedEnter = false
298: 			lastErr = send(attemptCtx, "agent.prompt", map[string]any{"target": paneID, "text": text, "wait": activity})
299: 		}
300: 		cancel()
301: 		if lastErr == nil {
302: 			return nil
303: 		}
304: 		if !isPromptStall(lastErr) && !isAgentBlocked(lastErr) {
305: 			return lastErr
306: 		}
307: 		if s.codexUpdatePrompt(ctx, paneID) {
308: 			return axi.Failure("codex_update_prompt", "Codex is waiting at its interactive self-update prompt", false, "Dismiss the update prompt or update Codex, then relaunch the Task")
309: 		}
310: 		if !isPromptStall(lastErr) {
311: 			return lastErr
312: 		}
313: 		if s.agentActive(ctx, paneID) {
314: 			return nil
315: 		}
316: 	}
317: 	return axi.Failure("prompt_not_delivered", fmt.Sprintf("the agent did not start working after %d prompt attempts: %v", launchPromptAttempts, lastErr), true, "Inspect the agent pane in Herdr, then retry")
