322: var pastePlaceholder = regexp.MustCompile(`\[Pasted text #[0-9]+`)
323: 
324: // promptOnScreen reports whether the pane shows text, ignoring whitespace so a
325: // prompt wrapped by the agent's input box still matches, or shows a paste
326: // placeholder. A stalled prompt was never submitted, so a copy on screen is
327: // the one left in the input.
328: func (s *Service) promptOnScreen(ctx context.Context, paneID, text string) bool {
329: 	screen := s.visibleScreen(ctx, paneID)
330: 	compact := func(value string) string { return strings.Join(strings.Fields(value), "") }
331: 	want := compact(text)
332: 	return want != "" && (strings.Contains(compact(screen), want) || pastePlaceholder.MatchString(screen))
333: }
